import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,viewFor,type GameCommand,type GameState} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const couragePhysicalScenarios=['courage-dia','courage-fear','courage-hidden','courage-reveal','courage-check-decline','courage-user-decline','courage-fail','courage-same','courage-evil','courage-poem','courage-canceled','courage-refill','courage-stopped','courage-later'] as const;
export type CouragePhysicalScenario=typeof couragePhysicalScenarios[number];
export function isCouragePhysicalScenario(name:string):name is CouragePhysicalScenario{return (couragePhysicalScenarios as readonly string[]).includes(name);}
export function courageMode(name:CouragePhysicalScenario){return{owner:name==='courage-same'?2:3,hidden:name==='courage-hidden'||name==='courage-reveal',fear:name==='courage-fear',poem:name==='courage-poem',abilityId:name==='courage-fear'?'c2-p06-r1c1-ab01':name==='courage-poem'?'c2-p03-r2c1-ab01':'c2-p06-r1c2-ab01'};}
/** Initial deal/training then real setup/reveal; stopped checker comes from a real prior mental double. */
export function makeCouragePhysicalScenario(name:CouragePhysicalScenario,players:{id:string;name:string}[],options:{checkerSpirit?:number}={}){
 const m=courageMode(name);let s=createGame(players,entropy(),{startingSeat:name==='courage-stopped'?2:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];for(const [i,p] of players.entries())assignCharacter(s,p.id,['小人のランバ',m.poem?'吟遊詩人のレスター':m.fear?'不死王ガドューラ':'魔聖母ディア',m.poem?'大神官ジル':'吟遊詩人のレスター',name==='courage-evil'?'黒騎士ガーウィン':'侍大将のシン'][i]!);for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};s.players[c]!.permanent!.spirit=20+(options.checkerSpirit??(name==='courage-fail'?0:20))-gameStats(s,c).spirit;
 const keep=[takeCard(s,a,'a2-p24-r1c2'),takeCard(s,a,'a2-p24-r2c2'),takeCard(s,a,'a2-p02-r2c3'),takeCard(s,a,'a2-p02-r1c3'),takeCard(s,c,'a2-p14-r1c2'),takeCard(s,players[m.owner]!.id,'a2-p01-r3c3')];for(const p of players)trimHand(s,p.id,...keep);
 let blood:string|undefined;if(name==='courage-refill'){blood=takeCard(s,a,'a2-p01-r1c3');s.players[a]!.hand=s.players[a]!.hand.filter(id=>id!==blood);}const ordinary=s.deck.filter(id=>getAction(id)!.category!=='open'),opens=s.deck.filter(id=>getAction(id)!.category==='open'),prefix=players.reduce((n,p)=>n+Math.max(0,5-s.players[p.id]!.hand.length),0);s.deck=blood?[...ordinary.slice(0,prefix),blood,...ordinary.slice(prefix),...opens]:[...ordinary,...opens];
 function act(actorId:string,command:GameCommand,dice=Array(100).fill(1)){const input={actorId,command},e={...entropy(),dice},r=transition(s,input,e);if(!r.ok)throw Error(`COURAGE_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('COURAGE_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('COURAGE_FIXTURE_CARDS');}
 function until(done:(s:GameState)=>boolean,dice:number[]){for(let n=0;n<300;n++){if(done(s))return;const w=s.windows?.at(-1);if(!w)throw Error('COURAGE_FIXTURE_WINDOW');act(w.participants[w.cursor]!,{type:'PASS'},dice);}throw Error('COURAGE_FIXTURE_LIMIT');}
 for(const id of [a,b,c,d])act(id,{type:'PASS_SETUP'});const first=name==='courage-stopped'?c:a;act(first,{type:'START_TURN'});act(first,{type:'CHOOSE_DRAW',draw:false});if(!m.hidden&&!m.poem)act(c,{type:'REVEAL_CHARACTER'});
 if(name==='courage-stopped'){act(c,{type:'ATTACK',cardInstanceId:'a2-p14-r1c2',targetIds:[b],dedicated:false});until(s=>s.windows?.at(-1)?.kind==='normal-defense',[2,2]);const o=viewFor(s,b).abilityOptions.find(o=>o.abilityId===m.abilityId)!;act(b,{type:'USE_ABILITY',abilityId:o.abilityId,targetEventId:o.targetEventId});until(s=>!s.windows?.length,[2,2]);if(!s.players[c]!.statuses?.some(t=>t.kind==='stopped'))throw Error('COURAGE_PRIOR_STOP');
  for(let n=0;n<100;n++){const id=s.seatOrder[s.turnSeat]!,w=s.windows?.at(-1);if(w)act(w.participants[w.cursor]!,{type:'PASS'});else if(s.phase==='action'){if(id===a)break;act(id,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(id=>!keep.includes(id)).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:false});else throw Error('COURAGE_FIXTURE_PHASE');}
 }
 if(s.phase!=='action'||s.seatOrder[s.turnSeat]!==a)throw Error('COURAGE_FIXTURE_TURN');if(blood&&s.deck[0]!==blood)throw Error('COURAGE_REFILL_PREFIX');return s;
}
